"""Restore historical outputs and original user bytes, then remove only regenerated old evidence."""
import pathlib,subprocess,json,hashlib,shutil
R=pathlib.Path(__file__).resolve().parents[1];O=R/'docs/content/r15';B=R/'.audit-tmp/r15-protected';protected=json.loads((O/'protected-baseline.json').read_text(encoding='utf-8'));plan=json.loads((O/'cleanup-plan.json').read_text(encoding='utf-8'));deleted={x['path'] for x in plan['candidates']};sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
def old(p):return (p.startswith('docs/evidence/') or p.startswith('docs/store/screenshots/') or (p.startswith('docs/content/r') and not p.startswith('docs/content/r15/')))
modified=subprocess.check_output(['git','diff','--name-only','-z'],cwd=R).decode().split('\0');restore=[p for p in modified if p and old(p) and p not in deleted and p not in protected];removed=[];archived=[]
for name in restore:
    if name.startswith('docs/store/screenshots/') and (R/name).is_file():
        dest=O/'regression-outputs'/name;dest.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(R/name,dest);archived.append({'source':name,'path':dest.relative_to(R).as_posix(),'sha256':sha(dest),'reason':'preserve current test capture before restoring original store bytes'})
if restore:
    spec=R/'.audit-tmp/r15-restore-paths';spec.write_bytes(('\0'.join(restore)+'\0').encode());subprocess.run(['git','restore','--worktree','--pathspec-from-file='+str(spec),'--pathspec-file-nul'],cwd=R,check=True)
for name in sorted(deleted):
    p=(R/name).resolve();assert p.is_relative_to(R.resolve()) and old(name)
    if p.is_file():removed.append({'path':name,'sha256':sha(p),'bytes':p.stat().st_size,'reason':'regenerated by tests after the original cleanup'});p.unlink()
others=subprocess.check_output(['git','ls-files','--others','--exclude-standard','-z'],cwd=R).decode().split('\0')
for name in others:
    if not name or name in protected or not old(name) or name.startswith('docs/store/screenshots/iphone-20-') or name.startswith('docs/store/screenshots/ipad-20-'):continue
    p=(R/name).resolve();assert p.is_relative_to(R.resolve())
    if not p.is_file() or p.suffix.lower()=='.md':continue
    if name.startswith('docs/store/'):
        dest=O/'regression-outputs'/name;dest.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(p,dest);archived.append({'source':name,'path':dest.relative_to(R).as_posix(),'sha256':sha(dest)})
    removed.append({'path':name,'sha256':sha(p),'bytes':p.stat().st_size,'reason':'new test output, absent before task; current receipts retained in R15'});p.unlink()
for name,h in protected.items():
    p=R/name
    if not p.is_file() or sha(p)!=h:
        assert name=='docs/evidence/R68/source-manifest.json','Unexpected change to protected user file; preserve live bytes: '+name
        backup=B/name;assert backup.is_file() and sha(backup)==h,name;p.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(backup,p)
assert all((R/n).is_file() and sha(R/n)==h for n,h in protected.items())
assert all(not (R/n).exists() for n in deleted)
(O/'regression-output-housekeeping.json').write_text(json.dumps({'status':'VERIFIED','historicalTrackedOutputsRestored':len(restore),'originalProtectedFilesVerified':len(protected),'deletedOldEvidenceStillAbsent':len(deleted),'regeneratedFilesRemoved':removed,'newStoreOutputsArchived':archived},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('VERIFIED original user files',len(protected),'; restored historical outputs',len(restore),'; removed regenerated files',len(removed))
